import {
	IsArray,
	IsEmail,
	IsEnum,
	IsNotEmpty,
	IsOptional,
	IsString,
	MinLength,
} from "class-validator";
import { ApiProperty, ApiPropertyOptional } from "@nestjs/swagger";
import { Transform } from "class-transformer";
import { PermissionCodes } from "src/permissions/enum/codes";

export class GeneratedInviteLinkResponseDTO {
	@ApiProperty({ description: "E-Mail-Adresse des einzuladenden Nutzers" })
	@IsNotEmpty()
	@IsString()
	@IsEmail()
	@Transform((param) => param.value.toLowerCase())
	email: string;

	@ApiProperty({ description: "ID des Kursfortschritts (courseProgressId)" })
	@IsNotEmpty()
	@IsString()
	courseProgressId: string;

	@ApiPropertyOptional({ description: "Optionaler Vorname" })
	@IsOptional()
	@IsString()
	@MinLength(2)
	firstName?: string;

	@ApiPropertyOptional({ description: "Optionaler Nachname" })
	@IsOptional()
	@IsString()
	@MinLength(2)
	lastName?: string;

	@ApiPropertyOptional({ description: "Optionale Berechtigungen" })
	@IsOptional()
	@IsArray()
	@IsEnum(PermissionCodes, { each: true })
	permissions?: PermissionCodes[];
}
